    .reg .u32 %r<32>;
    .reg .f32 %f<8>;
    .reg .pred %p<16>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [out_ptr];
    ld.param.u32 %r1, [total_elements];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;

    mov.u32 %r6, %nctaid.x;
    mul.lo.s32 %r7, %r6, %r3;

