    @%p2 bra IC_END;

    mov.u32 %r21, 0;
KD_LOOP:
    setp.ge.s32 %p3, %r21, 3;
    @%p3 bra KD_END;

    sub.s32 %r22, %r16, %r21;
    setp.lt.s32 %p4, %r22, 0;
    setp.ge.s32 %p5, %r22, 96;
    or.pred %p6, %p4, %p5;
    @%p6 bra KD_NEXT;

