    setp.ge.s32 %p11, %r25, 3;
    @%p11 bra KW_END;

    sub.s32 %r26, %r12, %r25;
    setp.lt.s32 %p12, %r26, 0;
    setp.ge.s32 %p13, %r26, 96;
    or.pred %p14, %p12, %p13;
    @%p14 bra KW_NEXT;

    mad.lo.s32 %r27, %r19, 48, %r20;
    mad.lo.s32 %r27, %r27, 96, %r22;
    mad.lo.s32 %r27, %r27, 96, %r24;
    mad.lo.s32 %r27, %r27, 96, %r26;
