    mad.lo.s32 %r28, %r28, 3, %r21;
    mad.lo.s32 %r28, %r28, 3, %r23;
    mad.lo.s32 %r28, %r28, 3, %r25;
    mul.wide.s32 %rd12, %r28, 4;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.f32 %f3, [%rd13];

    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_NEXT:
    add.s32 %r25, %r25, 1;
    bra KW_LOOP;
KW_END:

KH_NEXT:
    add.s32 %r23, %r23, 1;
    bra KH_LOOP;
KH_END:

KD_NEXT:
    add.s32 %r21, %r21, 1;
    bra KD_LOOP;
KD_END:

    add.s32 %r20, %r20, 1;
    bra IC_LOOP;
IC_END:

